package recovery

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"sync"
	"time"
)

// Recovery URL tokens are generated by an operator through the manager CLI
// and handed to a user out of band. Design choice: random tokens with only a
// SHA-256 digest stored, not stateless HMAC tokens. Single use and revocation
// require server-side state anyway, a random token needs no long-lived
// signing key that could leak, and 256 bits of entropy make a plain digest
// sufficient (no salt or slow KDF needed: the input is not guessable).
const (
	urlTokenBytes = 32
	// DefaultURLTokenTTL is the default lifetime of a recovery URL token.
	DefaultURLTokenTTL = 15 * time.Minute
	// MaxURLTokenTTL caps the lifetime an operator may request.
	MaxURLTokenTTL = time.Hour
)

var (
	// ErrTokenInvalid is returned for an unknown, used or burned token.
	ErrTokenInvalid = errors.New("recovery: invalid recovery token")
	// ErrTokenExpired is returned for an expired token.
	ErrTokenExpired = errors.New("recovery: recovery token expired")
	// ErrTokenWrongUser is returned when a token is presented for another
	// user. The token is burned, because it was evidently misdirected.
	ErrTokenWrongUser = errors.New("recovery: recovery token belongs to another user")
	// ErrInvalidTTL is returned for a non-positive or excessive lifetime.
	ErrInvalidTTL = errors.New("recovery: invalid token lifetime")
)

type urlToken struct {
	userID    string
	expiresAt time.Time
}

// URLTokens issues and redeems single-use recovery URL tokens. Only digests
// are kept; a used, expired or burned token is deleted. Issuing a new token
// for a user invalidates the user's previous token.
type URLTokens struct {
	mu     sync.Mutex
	now    Clock
	tokens map[[32]byte]urlToken
	byUser map[string][32]byte
}

// NewURLTokens returns an empty store. now may be nil for time.Now.
func NewURLTokens(now Clock) *URLTokens {
	if now == nil {
		now = time.Now
	}
	return &URLTokens{now: now, tokens: make(map[[32]byte]urlToken), byUser: make(map[string][32]byte)}
}

func digest(token string) [32]byte { return sha256.Sum256([]byte(token)) }

// Issue creates a token bound to userID. ttl 0 selects DefaultURLTokenTTL.
// The returned token is URL-safe and must be shown only once.
func (t *URLTokens) Issue(userID string, ttl time.Duration) (string, time.Time, error) {
	if userID == "" {
		return "", time.Time{}, errors.New("recovery: empty user ID")
	}
	if ttl == 0 {
		ttl = DefaultURLTokenTTL
	}
	if ttl < 0 || ttl > MaxURLTokenTTL {
		return "", time.Time{}, ErrInvalidTTL
	}
	buf := make([]byte, urlTokenBytes)
	if _, err := rand.Read(buf); err != nil {
		return "", time.Time{}, err
	}
	token := base64.RawURLEncoding.EncodeToString(buf)
	t.mu.Lock()
	defer t.mu.Unlock()
	exp := t.now().Add(ttl)
	if old, ok := t.byUser[userID]; ok {
		delete(t.tokens, old)
	}
	d := digest(token)
	t.tokens[d] = urlToken{userID: userID, expiresAt: exp}
	t.byUser[userID] = d
	return token, exp, nil
}

func (t *URLTokens) remove(d [32]byte, userID string) {
	delete(t.tokens, d)
	if t.byUser[userID] == d {
		delete(t.byUser, userID)
	}
}

// Redeem consumes a token for userID. Every outcome other than "unknown
// token" removes the token: success (single use), expiry and a wrong user.
// Callers should present all errors identically to the client.
func (t *URLTokens) Redeem(userID, token string) error {
	d := digest(token)
	t.mu.Lock()
	defer t.mu.Unlock()
	rec, ok := t.tokens[d]
	if !ok {
		return ErrTokenInvalid
	}
	t.remove(d, rec.userID)
	if !t.now().Before(rec.expiresAt) {
		return ErrTokenExpired
	}
	if rec.userID != userID {
		return ErrTokenWrongUser
	}
	return nil
}

// RevokeUser removes the user's outstanding token, if any.
func (t *URLTokens) RevokeUser(userID string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	if d, ok := t.byUser[userID]; ok {
		t.remove(d, userID)
	}
}

// Prune removes expired tokens and returns how many were removed.
func (t *URLTokens) Prune() int {
	t.mu.Lock()
	defer t.mu.Unlock()
	now := t.now()
	n := 0
	for d, rec := range t.tokens {
		if !now.Before(rec.expiresAt) {
			t.remove(d, rec.userID)
			n++
		}
	}
	return n
}
